# Code generated by Claude
"""G0 (g): the full check at raised target heights. The beaker is raised by about 5, 10 and 20 cm on a made-up box under it (a scratch scene: the check's own copy of the model, the box as one of its
object slots); the overlay picks the stance for each case; the full check (src/full_check.py) runs there once; the region's own verdict for the same case is printed beside it.

    MUJOCO_GL=egl python experiments/g0_raised_check.py [--raises 0.05 0.10 0.20] [--out docs/reports/g0_raised_check.json]
"""
import argparse
import json
import os
import time

import mujoco
import numpy as np

from experiments.bench_stance_validate import scene_objects
from src import bench_stance as bs
from src.full_check import FullCheck
from src.furniture_map import FurnitureMap
from src.home_clearance_map import HomeClearanceMap
from src.task_beaker_hotplate import bench_top_z
from src.task_config import BENCH_STANCE_CFG, TASK_CFG
from src.task_points import task_points

if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--raises", nargs="*", type=float, default=[0.05, 0.10, 0.20])
    ap.add_argument("--out", default="docs/reports/g0_raised_check.json")
    a = ap.parse_args()
    maps = bs.load_maps("data/reach_map")
    fc = FullCheck(maps=maps)
    m, rg, chk = fc.model, fc.rg, fc.chk
    yaw = TASK_CFG["staging_yaw"]
    qs = bs.pedestal_commands()
    cams = bs.camera_poses(m, qs, chk=chk, ref_stance=(*TASK_CFG["staging_xy"], yaw), cache_dir=BENCH_STANCE_CFG["cache_dir"])
    lmaps = {k: v for k, v in maps.items() if k[0] == "left"}
    furn = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    hcm = HomeClearanceMap(m, fc.scene_data, chk, np.array(TASK_CFG["beaker_xy"]), robot_geometry=rg, slack=0.0)
    extra = bs.make_extra_blocked(furn, rg, yaw, hcm.clear_mask)
    top = bench_top_z(m)
    bxy = np.array(TASK_CFG["beaker_xy"], float)
    base_q = fc.chk.q_scene.copy()
    out = []
    for r in a.raises:
        objs = scene_objects(m, fc.scene_data, raise_m=r)
        row = {"raise_m": r}
        try:
            res = bs.overlay(objs, lmaps, rg, cams, {"yaw": yaw, "open": TASK_CFG["bench_open"]}, extra, use_cache=False, say=lambda *_: None)
            row.update(stance=[res["xy"][0], res["xy"][1], yaw, res["q"]], region_covered=res["covered"], region_counts=res["counts"], region_score=list(res["score"]), region_run=list(res["run"]))
        except bs.BenchStanceError as e:
            row.update(stance=None, region_error=str(e)[:300])
            print(f"raise {r:.2f} m: the overlay finds no stance: {e}")
            out.append(row)
            continue
        # the scratch scene: the beaker raised, the box under it as an object, the grasp points raised
        q = base_q.copy()
        j = fc._beaker_free
        q[j + 2] += r
        fc.chk.q_scene = q
        box = {"id": "box", "outline": np.array([[bxy[0] - 0.06, bxy[1] - 0.06], [bxy[0] + 0.06, bxy[1] + 0.06]]), "height_range": (top, top + r)}
        pts = task_points(m, fc.scene_data)
        for p in pts:
            if p["path"] == "grasp":
                p["p"][2] += r
        t0 = time.perf_counter()
        fr = fc.check(tuple(row["stance"]), pts, objects=[box], use_cache=False)
        row.update(full_check_ok=bool(fr["ok"]), failed=fr["failed"], reason=fr["reason"], seconds=round(time.perf_counter() - t0, 1),
                   heights=[{k: (round(v, 4) if isinstance(v, float) else v) for k, v in h.items()} for h in fr["heights"]])
        print(f"raise {r:.2f} m: stance {np.round(row['stance'], 3).tolist()} region covers {res['covered']} counts {res['counts']} | full check {'PASS' if fr['ok'] else 'FAIL'} {fr['failed']} {fr['reason'][:200]}")
        out.append(row)
    fc.chk.q_scene = base_q
    json.dump(out, open(a.out + ".tmp", "w"), default=str)
    os.replace(a.out + ".tmp", a.out)
